-- =============================================================================
-- Areas of Bangalore and Pune (captain 2026-11-24, LIVE bug: area + PIN auto-fill
-- did nothing there). V11 seeded areas for HYD, GGN, DEL, NOI and MUM only, so BLR
-- and PNQ had areas only from the dev demo seed, and LIVE had none. These are main
-- residential localities, ACTIVE reference rows (not demo data, so every profile
-- gets them): 82 in BLR (ids 201-282) and 81 in PNQ (ids 301-381).
--
-- PIN source: India Post "All India Pincode Directory" (post office list with PIN
-- codes, Department of Posts, Open Government Data Platform India):
--   https://data.gov.in/resource/all-india-pincode-directory-till-last-month
--   file: https://www.data.gov.in/sites/default/files/all_india_PO_list_without_APS_offices_ver2_lat_long.csv
--   (sha256 6cb2edb44b568077b9d8a2962cffba05dafc1799e536c34fe9a30c75484612c1, read 2026-11-24)
-- Every PIN below is the pincode of the India Post office(s) named in the comment
-- above its area (districts Bangalore / Bangalore Rural with PIN 560xxx, and Pune
-- with PIN 410xxx-412xxx); none is typed by hand.
--
-- A locality is skipped when its city already has an ACTIVE or demo area of that
-- name, an area named like one of its aliases, or an area that lists this name
-- among its aliases (for example the demo seed's rows on dev), so the migration
-- never duplicates a place. A PENDING or HIDDEN match does not count (LIVE has a
-- user's PENDING proposal, which only its proposer can see): the locality is still
-- added, and when a PENDING or HIDDEN row already has its exact name (unique per
-- city) that row is made ACTIVE in place instead, with the reference name, aliases
-- and PIN codes, keeping its id and created_by so its homes stay on it; any PIN
-- code that row had which is not in the locality's India Post list is removed, so
-- auto-fill only offers sourced PINs. PIN codes are only added to or removed from
-- the row this migration added or made ACTIVE; ACTIVE rows are never touched.
-- Ids are fixed small numbers, far below the time-ordered ids the app makes (D-12).
-- Same portable subset as V1 (D-10).
-- =============================================================================

-- BLR
-- Koramangala: India Post Koramangala S.O 560034, Koramangala VI Bk S.O 560095
INSERT INTO areas (id, public_id, city_code, name, name_key, aliases, status, created_by, is_demo, created_at, updated_at)
SELECT 201, '01a205b3-d000-71ec-bcb9-ae5127dd55cf', code, 'Koramangala', 'koramangala', 'Kormangala', 'ACTIVE', NULL, FALSE, '2026-11-24 00:00:00.000', '2026-11-24 00:00:00.000' FROM cities
WHERE code = 'BLR' AND NOT EXISTS (SELECT 1 FROM areas WHERE city_code = 'BLR' AND (status = 'ACTIVE' OR is_demo = TRUE) AND (name_key = 'koramangala' OR name_key = 'kormangala' OR LOWER(aliases) LIKE '%koramangala%')) AND NOT EXISTS (SELECT 1 FROM areas WHERE city_code = 'BLR' AND name_key = 'koramangala');
INSERT INTO area_pincodes (area_id, pincode, created_at, updated_at) SELECT id, '560034', '2026-11-24 00:00:00.000', '2026-11-24 00:00:00.000' FROM areas WHERE city_code = 'BLR' AND name_key = 'koramangala' AND (id = 201 OR (status <> 'ACTIVE' AND is_demo = FALSE AND NOT EXISTS (SELECT 1 FROM areas m WHERE m.city_code = 'BLR' AND (m.status = 'ACTIVE' OR m.is_demo = TRUE) AND (m.name_key = 'koramangala' OR m.name_key = 'kormangala' OR LOWER(m.aliases) LIKE '%koramangala%')))) AND NOT EXISTS (SELECT 1 FROM area_pincodes p WHERE p.area_id = areas.id AND p.pincode = '560034');
INSERT INTO area_pincodes (area_id, pincode, created_at, updated_at) SELECT id, '560095', '2026-11-24 00:00:00.000', '2026-11-24 00:00:00.000' FROM areas WHERE city_code = 'BLR' AND name_key = 'koramangala' AND (id = 201 OR (status <> 'ACTIVE' AND is_demo = FALSE AND NOT EXISTS (SELECT 1 FROM areas m WHERE m.city_code = 'BLR' AND (m.status = 'ACTIVE' OR m.is_demo = TRUE) AND (m.name_key = 'koramangala' OR m.name_key = 'kormangala' OR LOWER(m.aliases) LIKE '%koramangala%')))) AND NOT EXISTS (SELECT 1 FROM area_pincodes p WHERE p.area_id = areas.id AND p.pincode = '560095');
DELETE FROM area_pincodes WHERE pincode NOT IN ('560034', '560095') AND area_id IN (SELECT id FROM areas WHERE city_code = 'BLR' AND name_key = 'koramangala' AND status <> 'ACTIVE' AND is_demo = FALSE AND NOT EXISTS (SELECT 1 FROM areas m WHERE m.city_code = 'BLR' AND (m.status = 'ACTIVE' OR m.is_demo = TRUE) AND (m.name_key = 'koramangala' OR m.name_key = 'kormangala' OR LOWER(m.aliases) LIKE '%koramangala%')));
UPDATE areas SET name = 'Koramangala', aliases = 'Kormangala', status = 'ACTIVE', updated_at = '2026-11-24 00:00:00.000' WHERE city_code = 'BLR' AND name_key = 'koramangala' AND status <> 'ACTIVE' AND is_demo = FALSE AND NOT EXISTS (SELECT 1 FROM (SELECT city_code, name_key, aliases, status, is_demo FROM areas) m WHERE m.city_code = 'BLR' AND (m.status = 'ACTIVE' OR m.is_demo = TRUE) AND (m.name_key = 'koramangala' OR m.name_key = 'kormangala' OR LOWER(m.aliases) LIKE '%koramangala%'));
